`timescale 1ns / 1ps
module freq_divbyfrac_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;

    // Inputs
    reg clk;
    reg rst_n;
    // Outputs
    wire clk_div;

    // Instantiate the Unit Under Test (UUT)
    freq_divbyfrac uut (
        .clk(clk), 
        .rst_n(rst_n), 
        .clk_div(clk_div)
    );
    always #5 clk = ~clk;

    integer error = 0;
    integer expected_value = 1;
    integer i;
    initial begin
        // Initialize Inputs
        clk = 1;
        rst_n = 0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        # 10 rst_n = 1;
        #120;

        $finish;
    end
    initial begin
        // $monitor("clk=%d, clk_div=%d",clk,clk_div);
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        #15;
        for (i = 0; i < 20; i = i + 1) begin
            if (clk_div !== expected_value) begin
                error = error + 1; 
                $display("Failed at%d: clk=%d, clk_div=%d (expected %d)", i,clk, clk_div, expected_value);
            end

            if (i < 2) expected_value = 1; 
            else if (i < 6) expected_value = 0; 
            else if (i < 9) expected_value = 1; 
            else if (i < 13) expected_value = 0; 
            else if (i < 16) expected_value = 1; 
            else if (i < 20) expected_value = 0; 
            else expected_value = 1; // Last five pairs
            #5;
        end
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
            end
        else begin
            $display("=========== Test completed with %d/20 failures ===========", error);
        end
    end




        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "clk_div,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", clk_div);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Tests...");

    // Initialize Inputs
    rst_n = 0;

    // Wait for stabilization
    #20;

    // ------------------------------------------------------------
    // Test Case 1: Normal Operation & Period Verification
    // ------------------------------------------------------------
    // Release reset on negedge to ensure clean setup
    @(negedge clk);
    rst_n = 1;

    // Run for multiple periods (Period = 7 cycles)
    // Targets: Operator mutations (cnt limit), Counter width faults
    // We expect the counter to wrap every 7 cycles.
    for (i = 0; i < 25; i = i + 1) begin
        @(posedge clk);
    end

    // ------------------------------------------------------------
    // Test Case 2: Asynchronous Reset Verification
    // ------------------------------------------------------------
    // Assert reset strictly between clock edges (Async check).
    // If the design has lost 'negedge rst_n' sensitivity (mutation), 
    // this async pulse will be ignored or delayed.
    @(posedge clk);
    #2; 
    rst_n = 0; // Assert Reset asynchronously
    #2;        // Pulse width 2ns (inside the high phase)
    rst_n = 1; // Deassert Reset

    // Allow time to observe reset effect (output should drop immediately)
    #10;

    // ------------------------------------------------------------
    // Test Case 3: Reset Priority & Recovery
    // ------------------------------------------------------------
    // Advance counter to mid-count (non-zero state)
    @(posedge clk);
    @(posedge clk);

    // Assert reset and hold across clock edge
    // Targets: Priority logic (if reset is synchronous or lower priority)
    rst_n = 0;
    #15; // Hold for 1.5 cycles to ensure edge crossing
    rst_n = 1;

    // Run to verify recovery and correct sequence generation
    for (i = 0; i < 15; i = i + 1) begin
        @(posedge clk);
    end

    // 4. Handover
    $display("LLM Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

